# --- Insert everything ---
increment_id = 1

for org_or_user, repos in REPOS.items():
    for r in repos:
        trit, color, name = gf3(increment_id)
        full = r["full_name"]
        parts = full.split("/")
        repo_name = parts[1] if len(parts) > 1 else full

        con.execute("""
            INSERT INTO world_increments VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, [increment_id, NOW, trit, color, name, "github_repo", org_or_user,
              "repo_snapshot", repo_name, org_or_user,
              hex(hash(full + r["pushed_at"]))[:16]])

        con.execute("""
            INSERT INTO repo_snapshots VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, [increment_id, NOW, increment_id, org_or_user, repo_name,
              full, r["language"], r["stars"], r["forks"],
              r["issues"], r["pushed_at"], r["description"]])

        increment_id += 1

# Aptos snapshots (all resource_not_found = 0 APT balance)
for world, addr in APTOS_ADDRS.items():
    con.execute("INSERT INTO aptos_snapshots VALUES (?, ?, ?, ?)",
                [NOW, world, addr, 0.0])

# Multisig probes
for pair, addr, sigs, healthy in MULTISIG_PROBES:
    con.execute("INSERT INTO multisig_probes VALUES (?, ?, ?, ?, ?)",
                [NOW, pair, addr, sigs, healthy])

